if(matchMedia('(pointer:fine)').matches&&!matchMedia('(prefers-reduced-motion:reduce)').matches){document.querySelectorAll('[data-float]').forEach((el,i)=>{el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect();el.style.setProperty('--float-x',`${(e.clientX-r.left-r.width/2)/r.width*14}px`);el.style.setProperty('--float-y',`${(e.clientY-r.top-r.height/2)/r.height*12}px`)});el.addEventListener('pointerleave',()=>{el.style.setProperty('--float-x','0px');el.style.setProperty('--float-y','0px')})});}
